// // // // // // // // // // // // // // // // // // // // // // // // // // // // //                                     style={{ fontSize: '0.72rem' }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //                                     title={`Appétence: ${rankInfo.score}/4`}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //                                   >
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //                                     {rankInfo.rank === 1 ? '1er' : `${rankInfo.rank}e`}
