// // // // // // // // // // // // // // // // // // // // // // // // //                               <div className="d-flex align-items-center justify-content-center gap-1 mb-1">
// // // // // // // // // // // // // // // // // // // // // // // // //                                 {isTogglingThisCell ? (
// // // // // // // // // // // // // // // // // // // // // // // // //                                   <Spinner
// // // // // // // // // // // // // // // // // // // // // // // // //                                     size="sm"
// // // // // // // // // // // // // // // // // // // // // // // // //                                     animation="border"
// // // // // // // // // // // // // // // // // // // // // // // // //                                     variant="info"
// // // // // // // // // // // // // // // // // // // // // // // // //                                     style={{ width: '0.75rem', height: '0.75rem', borderWidth: '1.5px' }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                   />
// // // // // // // // // // // // // // // // // // // // // // // // //                                 ) : (
// // // // // // // // // // // // // // // // // // // // // // // // //                                   <Form.Check
// // // // // // // // // // // // // // // // // // // // // // // // //                                     type="checkbox"
// // // // // // // // // // // // // // // // // // // // // // // // //                                     className="affectation-check"
// // // // // // // // // // // // // // // // // // // // // // // // //                                     checked={isAssignedToThisChef}
// // // // // // // // // // // // // // // // // // // // // // // // //                                     onChange={() =>
// // // // // // // // // // // // // // // // // // // // // // // // //                                       handleAssign(etud.id, isAssignedToThisChef ? '' : String(c.id), c.id)
// // // // // // // // // // // // // // // // // // // // // // // // //                                     }
// // // // // // // // // // // // // // // // // // // // // // // // //                                     title={isAssignedToThisChef ? `Affecté à ${c.nom}` : `Affecter à ${c.nom}`}
// // // // // // // // // // // // // // // // // // // // // // // // //                                     aria-label={`Affecter ${fullName} à ${c.nom}`}
// // // // // // // // // // // // // // // // // // // // // // // // //                                   />
// // // // // // // // // // // // // // // // // // // // // // // // //                                 )}
