// // // // // // // // // // // // // // // // // // // // // // // //                             {rankInfo.rank === 1 ? '1er choix' : `${rankInfo.rank}e choix`} ({rankInfo.score}/4)
// // // // // // // // // // // // // // // // // // // // // // // //                           </Badge>
// // // // // // // // // // // // // // // // // // // // // // // //                         ) : aff ? (
