// // // // // // // // // // // // // // // // // // // // // //                             : 'Non évalué';
// // // // // // // // // // // // // // // // // // // // // //                           const isTogglingThisCell = savingAffectationId === etud.id && savingAffectationChefId === c.id;

// // // // // // // // // // // // // // // // // // // // // //                           return (
// // // // // // // // // // // // // // // // // // // // // //                             <td
// // // // // // // // // // // // // // // // // // // // // //                               key={c.id}
// // // // // // // // // // // // // // // // // // // // // //                               className="col-chef"
// // // // // // // // // // // // // // // // // // // // // //                               style={{ backgroundColor: isAssignedToThisChef ? 'rgba(16, 185, 129, 0.15)' : 'inherit' }}
// // // // // // // // // // // // // // // // // // // // // //                             >
// // // // // // // // // // // // // // // // // // // // // //                               <div className="d-flex align-items-center justify-content-center mb-1">
// // // // // // // // // // // // // // // // // // // // // //                                 {isTogglingThisCell ? (
// // // // // // // // // // // // // // // // // // // // // //                                   <Spinner
// // // // // // // // // // // // // // // // // // // // // //                                     size="sm"
// // // // // // // // // // // // // // // // // // // // // //                                     animation="border"
// // // // // // // // // // // // // // // // // // // // // //                                     variant="info"
// // // // // // // // // // // // // // // // // // // // // //                                     style={{ width: '0.7rem', height: '0.7rem', borderWidth: '1.5px' }}
// // // // // // // // // // // // // // // // // // // // // //                                   />
// // // // // // // // // // // // // // // // // // // // // //                                 ) : (
// // // // // // // // // // // // // // // // // // // // // //                                   <span
// // // // // // // // // // // // // // // // // // // // // //                                     className={`affectation-pill ${isAssignedToThisChef ? 'is-assigned' : 'is-pending'}`}
// // // // // // // // // // // // // // // // // // // // // //                                     role="button"
// // // // // // // // // // // // // // // // // // // // // //                                     tabIndex={0}
// // // // // // // // // // // // // // // // // // // // // //                                     onClick={() =>
// // // // // // // // // // // // // // // // // // // // // //                                       handleAssign(etud.id, isAssignedToThisChef ? '' : String(c.id), c.id)
// // // // // // // // // // // // // // // // // // // // // //                                     }
// // // // // // // // // // // // // // // // // // // // // //                                     onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // //                                       if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // //                                         handleAssign(etud.id, isAssignedToThisChef ? '' : String(c.id), c.id);
// // // // // // // // // // // // // // // // // // // // // //                                       }
// // // // // // // // // // // // // // // // // // // // // //                                     }}
// // // // // // // // // // // // // // // // // // // // // //                                     title={
// // // // // // // // // // // // // // // // // // // // // //                                       isAssignedToThisChef
// // // // // // // // // // // // // // // // // // // // // //                                         ? `Affecté à ${c.nom} — cliquer pour retirer`
// // // // // // // // // // // // // // // // // // // // // //                                         : `Cliquer pour affecter à ${c.nom}`
// // // // // // // // // // // // // // // // // // // // // //                                     }
// // // // // // // // // // // // // // // // // // // // // //                                     aria-label={`Affecter ${fullName} à ${c.nom}`}
// // // // // // // // // // // // // // // // // // // // // //                                   >
// // // // // // // // // // // // // // // // // // // // // //                                     {isAssignedToThisChef ? '✓ Aff.' : 'Aff.'}
// // // // // // // // // // // // // // // // // // // // // //                                   </span>
// // // // // // // // // // // // // // // // // // // // // //                                 )}
// // // // // // // // // // // // // // // // // // // // // //                               </div>

// // // // // // // // // // // // // // // // // // // // // //                               <div className="d-flex align-items-center justify-content-center gap-1">
// // // // // // // // // // // // // // // // // // // // // //                                 <span
// // // // // // // // // // // // // // // // // // // // // //                                   className={`note-rank-square ${hasNote ? 'is-evaluated' : 'is-pending'}`}
// // // // // // // // // // // // // // // // // // // // // //                                   style={squareStyle}
// // // // // // // // // // // // // // // // // // // // // //                                   title={squareTitle}
// // // // // // // // // // // // // // // // // // // // // //                                 >
// // // // // // // // // // // // // // // // // // // // // //                                   {rankText}
// // // // // // // // // // // // // // // // // // // // // //                                 </span>

// // // // // // // // // // // // // // // // // // // // // //                                 {hasComment && (
// // // // // // // // // // // // // // // // // // // // // //                                   <button
// // // // // // // // // // // // // // // // // // // // // //                                     className="btn-comment-popup"
// // // // // // // // // // // // // // // // // // // // // //                                     onClick={() => handleOpenCommentPopup(etud, c, ev)}
// // // // // // // // // // // // // // // // // // // // // //                                     aria-label={`Voir le commentaire de ${c.nom} pour ${fullName}`}
// // // // // // // // // // // // // // // // // // // // // //                                   >
// // // // // // // // // // // // // // // // // // // // // //                                     💬
// // // // // // // // // // // // // // // // // // // // // //                                   </button>
// // // // // // // // // // // // // // // // // // // // // //                                 )}
// // // // // // // // // // // // // // // // // // // // // //                               </div>
// // // // // // // // // // // // // // // // // // // // // //                             </td>
// // // // // // // // // // // // // // // // // // // // // //                           );
// // // // // // // // // // // // // // // // // // // // // //                         })}
// // // // // // // // // // // // // // // // // // // // // //                       </tr>
// // // // // // // // // // // // // // // // // // // // // //                     );
// // // // // // // // // // // // // // // // // // // // // //                   })}
// // // // // // // // // // // // // // // // // // // // // //                 </tbody>
// // // // // // // // // // // // // // // // // // // // // //               </Table>
// // // // // // // // // // // // // // // // // // // // // //             </div>
// // // // // // // // // // // // // // // // // // // // // //           </div>
// // // // // // // // // // // // // // // // // // // // // //         )}
