// // // // // // // // // // // // // // // // // // // // // //               name="reset-eval-target"
// // // // // // // // // // // // // // // // // // // // // //               label="Vider TOUT (Évaluations + Affectations)"
// // // // // // // // // // // // // // // // // // // // // //               checked={resetTarget === 'both'}
