// // // // // // // // // // // // // // // // // // // // //                           {etud.lm_path && (
// // // // // // // // // // // // // // // // // // // // //                             <a href={getDocumentPublicUrl(etud.lm_path)} target="_blank" rel="noopener noreferrer" className="badge bg-secondary text-decoration-none">
// // // // // // // // // // // // // // // // // // // // //                               ✉️ LM
