// // // // // // // // // // // // // // // // // // // // //                                 tabIndex={0}
// // // // // // // // // // // // // // // // // // // // //                                 onClick={() => handleOpenRadar(etud)}
// // // // // // // // // // // // // // // // // // // // //                                 onKeyDown={(e) => {
