// // // // // // // // // // // // // // // // // // // // //                                     className={`affectation-pill ${isAssignedToThisChef ? 'is-assigned' : 'is-pending'}`}
// // // // // // // // // // // // // // // // // // // // //                                     role="button"
// // // // // // // // // // // // // // // // // // // // //                                     tabIndex={0}
// // // // // // // // // // // // // // // // // // // // //                                     onClick={() =>
// // // // // // // // // // // // // // // // // // // // //                                       handleAssign(etud.id, isAssignedToThisChef ? '' : String(c.id), c.id)
// // // // // // // // // // // // // // // // // // // // //                                     }
// // // // // // // // // // // // // // // // // // // // //                                     onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // //                                       if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // //                                         handleAssign(etud.id, isAssignedToThisChef ? '' : String(c.id), c.id);
// // // // // // // // // // // // // // // // // // // // //                                       }
// // // // // // // // // // // // // // // // // // // // //                                     }}
// // // // // // // // // // // // // // // // // // // // //                                     title={
// // // // // // // // // // // // // // // // // // // // //                                       isAssignedToThisChef
// // // // // // // // // // // // // // // // // // // // //                                         ? `Affecté à ${c.nom} — cliquer pour retirer`
// // // // // // // // // // // // // // // // // // // // //                                         : `Cliquer pour affecter à ${c.nom}`
// // // // // // // // // // // // // // // // // // // // //                                     }
// // // // // // // // // // // // // // // // // // // // //                                     aria-label={`Affecter ${fullName} à ${c.nom}`}
// // // // // // // // // // // // // // // // // // // // //                                   >
// // // // // // // // // // // // // // // // // // // // //                                     {isAssignedToThisChef ? '✓ Aff.' : 'Aff.'}
// // // // // // // // // // // // // // // // // // // // //                                   </span>
// // // // // // // // // // // // // // // // // // // // //                                 )}
// // // // // // // // // // // // // // // // // // // // //                               </div>

// // // // // // // // // // // // // // // // // // // // //                               <div className="d-flex align-items-center justify-content-center gap-1">
// // // // // // // // // // // // // // // // // // // // //                                 <span
